def blotling():
    # An ink blot with two drips for feet and a quill-tip curl on its head.
    blob = union(ellipse_mask(28, 38, 14, 11), ellipse_mask(20, 32, 8, 8), ellipse_mask(38, 34, 7, 7))
    return [
        Part(blob, "dark"),
        E(22, 50, 3, 4, "dark"), E(34, 51, 3, 3, "dark"),                       # drips
        E(46, 46, 2, 2, "dark"), E(50, 42, 1, 1, "dark"),                       # splash dots
        P([(24, 24), (30, 14), (34, 16), (28, 26)], "mid"),                     # quill curl
        E(28, 42, 7, 3, "mid", outline=False),                                  # sheen
        eye(16, 32, big=True), eye(25, 32, big=True),
        Stamp(19, 40, [".00."]),
    ]


